void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = texture(iChannel0, uv).rgb;

    // Output to screen
    fragColor = vec4(col,1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 lastFrameRight = texture(iChannel0, (fragCoord+vec2(-1.0, 0.0))/iResolution.xy);

    float ans= mix(0.0f, 1.0f, round(lastFrameRight.r));

    if(iMouse.z>0.0f)
        ans = mix(0.0f, 1.0f, floor(iMouse.x/fragCoord.x));

    fragColor = vec4(ans,0.0,0.0,1.0);
}
